import sys
from collections import defaultdict

def main():
    import sys
    input = sys.stdin.read().split()
    index = 0
    n = int(input[index])
    m = int(input[index + 1])
    index += 2
    points = list(map(int, input[index:index + n]))
    index += n
    segments = []
    for _ in range(m):
        l = int(input[index])
        r = int(input[index + 1])
        segments.append((l, r))
        index += 2

    # Create a graph where each node represents a point
    # An edge between two nodes means they cannot have the same color
    graph = defaultdict(list)
    for l, r in segments:
        for i in range(n):
            if l <= points[i] <= r:
                for j in range(i + 1, n):
                    if l <= points[j] <= r:
                        graph[points[i]].append(points[j])
                        graph[points[j]].append(points[i])

    # Try to color the graph using two colors (0 and 1)
    color = {}

    def dfs(node, c):
        color[node] = c
        for neighbor in graph[node]:
            if neighbor not in color:
                if not dfs(neighbor, 1 - c):
                    return False
            elif color[neighbor] == c:
                return False
        return True

    # Check if we can color the graph
    for point in points:
        if point not in color:
            if not dfs(point, 0):
                print(-1)
                return

    # Output the coloring
    point_to_color = {point: color[point] for point in points}
    result = [point_to_color[point] for point in points]
    print(' '.join(map(str, result)))

if __name__ == "__main__":
    main()
